BEGIN;

INSERT INTO public.categories (subject_id, name, color, sort_order)
SELECT id, '手で計算する統計', '#6ab0a0', 9 FROM public.subjects WHERE slug = 'stats-basics'
ON CONFLICT (subject_id, name) DO NOTHING;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES
  ('stats10-q01', '手で計算する統計',
   '5人が受けたテストの点数は 56点・58点・60点・62点・64点。この5人の平均点は？',
   NULL::text,
   '["60点", "61点", "58点", "75点"]',
   0,
   '[0]',
   'single',
   '{"asked": "5人分の点数から平均点を手で計算する。", "point": "平均＝全部足して人数で割る。5人なら合計を5で割る。", "kid": "5人の点数をぜんぶ合わせて、5人で仲良く同じ量に配り直したらいくつになるか、という数。", "eg": "5人のお小遣いをいったん全部集めて、また5人に同じ金額ずつ配り直すイメージ。配り直した後の1人分が平均。", "terms": [["平均（へいきん）", "全部の値を足して、個数で割った値"], ["合計", "全部を足し合わせた数"]], "think": "56,58,60,62,64を全部足すと300。これを人数の5で割ると60。「足してから人数で割る」の2ステップさえ守れば、どんな点数でも平均は出せる。", "calc": "点数    56  58  60  62  64\n合計    56+58+60+62+64 = 300\n平均    300 ÷ 5 = 60点", "vs": "中央値（真ん中の人の点数）は今回たまたま平均と同じ60点になるが、これは点数が綺麗に並んでいるからの偶然。ふつうは平均と中央値は別の値になる。", "why_asked": "分散や標準偏差はすべて「平均との差」から計算が始まる。この先のq02〜q08は、ここで出した平均60点を使い続ける。", "usecase": "テストの平均点、月々の支出の平均、工場で作った部品の重さの平均など、集団の「ふつうの値」を知りたいときに使う。", "opt": ["正解。56+58+60+62+64=300を5人で割ると60点。", "合計300を5で割らず、足し算のどこかで1点多く数えた場合の値。", "5人のうち一部の点数だけを見て平均だと勘違いした場合の値。", "合計300を5人ではなく4人で割ってしまった場合の値（300÷4）。"], "viz": "<svg viewBox=\"0 0 340 128\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n    <text x=\"170\" y=\"20\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">5人の点数を数直線に置く</text>\n    <line x1=\"30\" y1=\"60\" x2=\"310\" y2=\"60\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/>\n    <circle cx=\"40\" cy=\"60\" r=\"5\" fill=\"#3b82f6\"/><text x=\"40\" y=\"46\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\">56</text><circle cx=\"100\" cy=\"60\" r=\"5\" fill=\"#3b82f6\"/><text x=\"100\" y=\"46\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\">58</text><circle cx=\"170\" cy=\"60\" r=\"5\" fill=\"#3b82f6\"/><text x=\"170\" y=\"46\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">60</text><circle cx=\"240\" cy=\"60\" r=\"5\" fill=\"#3b82f6\"/><text x=\"240\" y=\"46\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\">62</text><circle cx=\"300\" cy=\"60\" r=\"5\" fill=\"#3b82f6\"/><text x=\"300\" y=\"46\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\">64</text>\n    <polygon points=\"170,78 162,94 178,94\" fill=\"#c9a04a\"/>\n    <text x=\"170\" y=\"112\" fill=\"#c9a04a\" font-size=\"10\" text-anchor=\"middle\">支点＝平均はいくつ？</text>\n    </svg>"}'),  ('stats10-q02', '手で計算する統計',
   '前回、5人の平均は60点と分かった。64点を取った人は、平均よりどれだけ高いか（偏差）？',
   NULL::text,
   '["+4点", "-4点", "4点", "64点"]',
   0,
   '[0]',
   'single',
   '{"asked": "個人の点数と平均との差（偏差）を求める。", "point": "偏差＝その人の点数−平均。平均より高ければプラス、低ければマイナスになる。", "kid": "「平均より高いか低いか」「どれだけ離れているか」を、プラス・マイナスの符号付きの数で表したもの。", "eg": "山の頂上(平均)を基準にして、自分がどれだけ上にいるか下にいるかを表す標高差のようなもの。頂上より上ならプラス、下ならマイナス。", "terms": [["偏差（へんさ）", "その人の値から平均を引いた差。プラスかマイナスの符号を持つ"]], "think": "64点から平均60点を引くと+4。プラスがつくのは「平均より高かった」ことを表すサインで、点数そのものとは別の情報。符号を落とすと「平均よりどっちに離れているか」が消えてしまう。", "calc": "点数     56  58  60  62  64\n平均との差 -4  -2   0  +2  +4  ← 偏差\n64点の偏差 = 64 − 60 = +4", "vs": "符号を付けずに「4点」とだけ答えると、平均より高いのか低いのかの情報が消えてしまう。偏差は符号込みで初めて意味を持つ。", "why_asked": "この先の分散・標準偏差・z値・偏差値は、すべてこの偏差の計算から始まる。ここで符号を落とす癖がつくと後の計算全部がずれる。", "usecase": "自分のテストの点数が平均よりどれだけ良かったか悪かったかを一言で言うときに使う考え方。", "opt": ["正解。64−60=+4。平均より4点高いというプラスの偏差。", "引き算の順番を逆にして60−64を計算した場合の値。", "符号（プラスかマイナスか）を付け忘れた場合の値。", "引き算をせず、点数そのものを答えてしまった場合の値。"], "viz": "<svg viewBox=\"0 0 340 128\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n    <text x=\"170\" y=\"18\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">平均60点との差（偏差）</text>\n    <line x1=\"30\" y1=\"55\" x2=\"310\" y2=\"55\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/>\n    <line x1=\"170\" y1=\"55\" x2=\"170\" y2=\"70\" stroke=\"#c9a04a\" stroke-width=\"1.3\"/>\n    <circle cx=\"40\" cy=\"55\" r=\"5\" fill=\"#3b82f6\"/><text x=\"40\" y=\"41\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\">56</text><text x=\"40\" y=\"98\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">-4</text><circle cx=\"100\" cy=\"55\" r=\"5\" fill=\"#3b82f6\"/><text x=\"100\" y=\"41\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\">58</text><text x=\"100\" y=\"98\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">-2</text><circle cx=\"170\" cy=\"55\" r=\"5\" fill=\"#3b82f6\"/><text x=\"170\" y=\"41\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\">60</text><text x=\"170\" y=\"98\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">0</text><circle cx=\"240\" cy=\"55\" r=\"5\" fill=\"#3b82f6\"/><text x=\"240\" y=\"41\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\">62</text><text x=\"240\" y=\"98\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">+2</text><circle cx=\"300\" cy=\"55\" r=\"5\" fill=\"#60a5fa\"/><text x=\"300\" y=\"41\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\">64</text><text x=\"300\" y=\"98\" fill=\"#60a5fa\" font-size=\"10\" text-anchor=\"middle\">+4</text>\n    <text x=\"170\" y=\"112\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">64点は支点(平均)よりどれだけ離れてる？</text>\n    </svg>"}'),  ('stats10-q03', '手で計算する統計',
   '前回出した5人の偏差は -4, -2, 0, +2, +4。この5つを全部足すといくつになる？',
   NULL::text,
   '["0", "-8", "+8", "4"]',
   0,
   '[0]',
   'single',
   '{"asked": "5人分の偏差（平均との差）を全部足すといくつになるか。", "point": "偏差を全部足すと必ず0になる。平均より上と下がちょうど釣り合うから。", "kid": "平均より高い人のプラスと、平均より低い人のマイナスが、ちょうど同じ量だけあるので、足すとゼロで消えてしまう。", "eg": "天秤の支点を平均の位置に置いたら、左右で釣り合っているのと同じ。片方に偏った重さが乗っていたら、そこが平均ではない。", "terms": [["偏差の合計", "各人の偏差(平均との差)を全部足した値。常に0になる"]], "think": "-4と+4、-2と+2がそれぞれ打ち消し合い、残る0を足しても0のまま。だから偏差をそのまま足して「散らばりの平均」にしようとしても、答えは常に0になってしまい、散らばりの大きさを測れない。この困りごとを解決するために、次は偏差を2乗して符号を消す。", "calc": "偏差    -4  -2   0  +2  +4\n合計    (-4)+(-2)+0+(+2)+(+4) = 0", "vs": "「散らばりが大きいほど合計も大きくなるはず」と思いがちだが、偏差の合計はどんなデータでも常に0。散らばりの大きさは別の計算（2乗して平均する＝分散）で測る必要がある。", "why_asked": "「平均との差を平均すればばらつきが分かるのでは」という自然な発想が、なぜ通用しないのかを理解する山場。ここが分散という指標が生まれた理由そのもの。", "usecase": "分散や標準偏差の計算式を丸暗記ではなく理解して使うために、まずこの「合計は0になる」という事実を押さえておく。", "opt": ["正解。マイナスとプラスがちょうど打ち消し合い、合計は必ず0になる。", "マイナスの符号をそのまま残して合計を計算した場合に起こり得る値。", "マイナスを無視して絶対値のまま全部プラスとして足した場合の値。", "5つのうち1つを数え忘れて合計を計算した場合の値。"], "viz": "<svg viewBox=\"0 0 340 120\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n    <text x=\"170\" y=\"18\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">偏差の合計＝天秤はつり合う</text>\n    <line x1=\"60\" y1=\"55\" x2=\"280\" y2=\"55\" stroke=\"#2a2f3f\" stroke-width=\"2\"/>\n    <polygon points=\"170,55 160,72 180,72\" fill=\"#8892a4\"/>\n    <text x=\"90\" y=\"42\" fill=\"#c47070\" font-size=\"11\" text-anchor=\"middle\">-4 -2</text>\n    <text x=\"250\" y=\"42\" fill=\"#6ab08d\" font-size=\"11\" text-anchor=\"middle\">+2 +4</text>\n    <text x=\"170\" y=\"42\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">0</text>\n    <line x1=\"90\" y1=\"55\" x2=\"90\" y2=\"46\" stroke=\"#c47070\"/>\n    <line x1=\"250\" y1=\"55\" x2=\"250\" y2=\"46\" stroke=\"#6ab08d\"/>\n    <text x=\"170\" y=\"100\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">マイナスとプラスが打ち消し合う → 合計は？</text>\n    </svg>"}'),  ('stats10-q04', '手で計算する統計',
   '偏差の合計はいつも0で使えない。そこで各偏差を2乗する。64点の人の偏差+4を2乗するといくつ？',
   NULL::text,
   '["16", "8", "-16", "4"]',
   0,
   '[0]',
   'single',
   '{"asked": "偏差を2乗するとどうなるか。プラスもマイナスも2乗するとどちらもプラスになる性質を確かめる。", "point": "偏差を2乗すると符号が消えて必ずプラスになる。マイナス×マイナスもプラス×プラスも、答えはプラス。", "kid": "+4を2乗するとは+4×+4のこと。マイナスの偏差(例えば−4)を2乗しても、−4×−4でやっぱりプラスになる。", "eg": "1辺の長さが4の正方形の面積は4×4=16。長さがマイナス4というのは実際にはないが、偏差を「2乗して面積のように扱う」と考えると、プラスの偏差もマイナスの偏差も同じ土俵で比べられる。", "terms": [["2乗", "同じ数を2回掛けること。符号がプラスでもマイナスでも、2乗した結果は必ずプラスになる"]], "think": "偏差の合計が0になって使えなかったのは、プラスとマイナスが混ざっていたから。2乗すればすべてプラスになるので、足しても0で消えることがなくなり、散らばりの大きさとして扱える。これが分散の計算で2乗を使う理由。", "calc": "偏差      -4   -2    0   +2   +4\n2乗       16    4    0    4   16  ← マイナスが消える\n64点の分  (+4)×(+4) = 16", "vs": "「2乗」を「2倍」と混同すると+4が8になってしまう。2乗は同じ数を2回掛けること、2倍は2を1回掛けること。まったく別の計算。", "why_asked": "分散の式に出てくる「2乗」がなぜ必要なのかは、q03の「合計が0になる」問題を解決する工夫だと分かっていないと丸暗記になる。", "usecase": "分散・標準偏差・最小二乗法など、統計のいたるところで「差を2乗する」という工夫が出てくる。その最初の一歩。", "opt": ["正解。+4×+4=16。2乗すると符号が消えてプラスになる。", "2乗ではなく2倍（+4×2）を計算した場合の値。", "2乗してもマイナスの符号が残ると勘違いした場合の値。", "2乗をせず、偏差の値をそのまま書いてしまった場合の値。"], "viz": "<svg viewBox=\"0 0 340 126\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n    <text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">偏差を2乗＝正方形の面積にする</text>\n    <rect x=\"30\" y=\"40\" width=\"40\" height=\"40\" fill=\"#3b82f6\" opacity=\"0.55\"/><text x=\"50.0\" y=\"96\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">-4→16</text>\n    <rect x=\"95\" y=\"60\" width=\"20\" height=\"20\" fill=\"#3b82f6\" opacity=\"0.55\"/><text x=\"105.0\" y=\"96\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">-2→4</text>\n    <rect x=\"150\" y=\"76\" width=\"4\" height=\"4\" fill=\"#8892a4\" opacity=\"0.55\"/><text x=\"152.0\" y=\"96\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">0→0</text>\n    <rect x=\"195\" y=\"60\" width=\"20\" height=\"20\" fill=\"#60a5fa\" opacity=\"0.55\"/><text x=\"205.0\" y=\"96\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">+2→4</text>\n    <rect x=\"250\" y=\"40\" width=\"40\" height=\"40\" fill=\"#60a5fa\" opacity=\"0.55\"/><text x=\"270.0\" y=\"96\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">+4→?</text>\n    <text x=\"170\" y=\"112\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">2乗すると符号が消え、全部プラスになる</text>\n    </svg>"}'),  ('stats10-q05', '手で計算する統計',
   '5人の偏差の2乗は 16, 4, 0, 4, 16。これを全部足して5人で割った値（分散）はいくつ？',
   NULL::text,
   '["8", "40", "4", "10"]',
   0,
   '[0]',
   'single',
   '{"asked": "偏差の2乗を平均する＝分散を手で求める。", "point": "分散＝偏差の2乗を全部足して人数で割った値。散らばりの大きさを表す。", "kid": "「平均からどれだけ離れているか」を2乗して符号を消した後、その2乗の値をもう一度平均し直したもの。", "eg": "5人がそれぞれ平均から離れた分の「面積」（q04の正方形）を全部集めて、5人で均等に配り直したときの1人分の面積、というイメージ。", "terms": [["分散（ぶんさん）", "偏差の2乗を平均した値。データの散らばりの大きさを表す"]], "think": "偏差をそのまま平均すると0になって使えなかった（q03）。2乗してプラスに揃えた値（q04）なら平均しても0にならず、散らばりが大きいほど大きな値になる。この「2乗した偏差の平均」が分散。", "calc": "2乗      16   4   0   4  16\n合計     16+4+0+4+16 = 40\n分散     40 ÷ 5 = 8", "vs": "分散の単位は「点」ではなく「点の2乗」になっている点に注意。2乗したまま平均しているので、元の点数の単位から離れてしまっている。これを点の単位に戻すのが次のq06（標準偏差）。", "why_asked": "分散は標準偏差・z値・偏差値すべての土台になる数。手計算で「合計を人数で割る」という平均と同じ操作をしているだけだと分かれば怖くない。", "usecase": "テストの点数のばらつき具合、工場製品の寸法のばらつき、株価の変動の大きさなど「どれくらいバラついているか」を数値で表したいときに使う。", "opt": ["正解。16+4+0+4+16=40を5人で割ると8。", "5で割るのを忘れて、2乗の合計40のまま答えてしまった場合の値。", "40を5ではなく10で割ってしまった場合の値（人数を倍に数えた）。", "40を5ではなく4で割ってしまった場合の値（人数を1人少なく数えた）。"], "viz": "<svg viewBox=\"0 0 340 128\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n    <text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">2乗の値を集めて5等分＝分散</text>\n    <rect x=\"30\" y=\"40\" width=\"270\" height=\"16\" fill=\"#3b82f6\" opacity=\"0.4\"/>\n    <text x=\"35\" y=\"52\" fill=\"#e8eaf0\" font-size=\"9\">16</text>\n    <text x=\"90\" y=\"52\" fill=\"#e8eaf0\" font-size=\"9\">4</text>\n    <text x=\"150\" y=\"52\" fill=\"#e8eaf0\" font-size=\"9\">0</text>\n    <text x=\"205\" y=\"52\" fill=\"#e8eaf0\" font-size=\"9\">4</text>\n    <text x=\"260\" y=\"52\" fill=\"#e8eaf0\" font-size=\"9\">16</text>\n    <text x=\"170\" y=\"76\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">合計40を5人で均等に分けると…</text>\n    <polygon points=\"170,84 162,100 178,100\" fill=\"#c9a04a\"/>\n    <text x=\"170\" y=\"115\" fill=\"#c9a04a\" font-size=\"10\" text-anchor=\"middle\">1人あたり＝分散</text>\n    </svg>"}'),  ('stats10-q06', '手で計算する統計',
   '分散は8と分かった。この√8（電卓で計算すると2.828…）を小数第2位までにすると、標準偏差はいくつ？',
   NULL::text,
   '["2.83点", "8点", "5.66点", "1.41点"]',
   0,
   '[0]',
   'single',
   '{"asked": "分散から標準偏差を求める。√（ルート）を使って単位を点に戻す。", "point": "標準偏差＝分散の√（平方根）。分散のままだと単位が「点の2乗」で扱いにくいので、√で元の「点」に戻す。", "kid": "分散は偏差を2乗して作った数なので、単位も「2乗」されたまま。√はその2乗を「元に戻す」計算で、平方根と呼ぶ。", "eg": "1辺4の正方形の面積は16。逆に「面積16の正方形の1辺は？」と聞かれたら答えは4。√16=4というのはこの「面積から1辺の長さに戻す」計算のこと。今回は面積が8なので、1辺はぴったりした整数にならず2.83になる。", "terms": [["標準偏差（σ、読みはシグマ）", "分散の平方根(√)。データの散らばりを、元の点数と同じ単位で表した値"], ["√（平方根）", "2乗する前の元の数を求める計算。√16=4のように使う"]], "think": "分散8は「点の2乗」という扱いにくい単位。√8とすることで2乗を元に戻し、「点」という元の単位に戻せる。2.828…という中途半端な数になるのは、8がちょうどいい数の2乗ではないから。以後はこの値を2.83と決めて使う。", "calc": "分散       8（単位は「点²」）\n√8        = 2.828… （電卓の値）\n標準偏差   2.83点（小数第2位までに固定）", "vs": "分散8と標準偏差2.83は同じ散らばりを表す数だが、単位が違う。分散をそのまま「散らばりの大きさ」と言うと単位が「点の2乗」でわかりにくいので、実際の会話では標準偏差(点のまま)を使うことが多い。", "why_asked": "標準偏差は、この後のz値・偏差値の計算で「1目盛りの大きさ」として使われる。分散との違い(2乗されているかいないか)を理解していないとこの先の計算で混乱する。", "usecase": "偏差値の計算、テストの点数の「ばらつき具合」を人に説明するとき、品質管理で製品の寸法のばらつきを報告するときなど。", "opt": ["正解。√8=2.828…を小数第2位までにすると2.83。", "√を取らず、分散8をそのまま標準偏差と答えてしまった場合の値。", "正しい2.83を2倍にしてしまった場合の値。", "正しい2.83を半分にしてしまった場合の値。"], "viz": "<svg viewBox=\"0 0 340 128\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n    <text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">分散(面積8)の1辺の長さが標準偏差</text>\n    <rect x=\"105\" y=\"35\" width=\"46\" height=\"46\" fill=\"#3b82f6\" opacity=\"0.5\"/>\n    <text x=\"128\" y=\"62\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\">面積8</text>\n    <text x=\"230\" y=\"62\" fill=\"#60a5fa\" font-size=\"13\" text-anchor=\"middle\">√8 = ?</text>\n    <text x=\"170\" y=\"98\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">分散は単位が「点²」のまま</text>\n    <text x=\"170\" y=\"112\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">標準偏差は単位が「点」に戻る</text>\n    </svg>"}'),  ('stats10-q07', '手で計算する統計',
   '平均60点・標準偏差2.83点のとき、64点の人のz値（小数第1位まで）はいくつ？',
   NULL::text,
   '["+1.4", "+4", "+2.83", "-1.4"]',
   0,
   '[0]',
   'single',
   '{"asked": "偏差を標準偏差で割って、z値（標準化した値）を求める。", "point": "z値＝偏差÷標準偏差。「平均から標準偏差何個ぶん離れているか」を表す数。", "kid": "偏差(+4点)だけだと「4点差」という情報しかないが、これを標準偏差(2.83点)で割ると「標準偏差の何個ぶん離れているか」という、他のテストとも比べられる数に変わる。", "eg": "「4点差」は物差しの目盛りが1点ずつのときの話。標準偏差2.83点を新しい目盛り1個ぶんとして測り直すと、4点差は目盛り約1.4個ぶんになる。これがz値。", "terms": [["z値", "偏差を標準偏差で割った値。平均0・標準偏差1個ぶんを1とする共通のものさし"]], "think": "偏差+4はこのテストだけの「点数の差」。標準偏差2.83で割ることで「標準偏差いくつぶん離れているか」という、テストが違っても比べられる共通の数値になる。これがz値。", "calc": "偏差         +4\nz値          (64−60) ÷ 2.83 = 4 ÷ 2.83 = 1.413…\nz値（丸め）   +1.4", "vs": "z値と偏差(+4)は別の数。偏差は「点差」、z値は「標準偏差の何個ぶん」という比率。割り算をせず偏差をそのまま答えると点差とz値を混同することになる。", "why_asked": "z値は、この後の偏差値の計算の土台になるだけでなく、平均も標準偏差も違う複数のテストを公平に比べるための共通のものさし。", "usecase": "偏差値の計算、模試の回によって難易度が違う成績の比較、複数の検査値をまとめて評価するときなど。", "opt": ["正解。(64−60)÷2.83=1.413…を小数第1位にすると+1.4。", "標準偏差で割るのを忘れて、偏差+4をそのまま答えてしまった場合の値。", "割り算の分子と分母を逆にして2.83÷4に近い形で計算した場合の値。", "符号を逆にして計算してしまった場合の値。"], "viz": "<svg viewBox=\"0 0 340 124\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n    <text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">標準偏差いくつぶん離れているか＝z値</text>\n    <line x1=\"30\" y1=\"60\" x2=\"310\" y2=\"60\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/>\n    <line x1=\"170\" y1=\"54\" x2=\"170\" y2=\"66\" stroke=\"#8892a4\"/>\n    <text x=\"170\" y=\"80\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">60点(z=0)</text>\n    <circle cx=\"270\" cy=\"60\" r=\"5\" fill=\"#60a5fa\"/>\n    <text x=\"270\" y=\"46\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\">64点</text>\n    <text x=\"270\" y=\"80\" fill=\"#60a5fa\" font-size=\"9\" text-anchor=\"middle\">標準偏差2.83の何個ぶん？</text>\n    <text x=\"170\" y=\"108\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">(64−60)÷2.83 = z値</text>\n    </svg>"}'),  ('stats10-q08', '手で計算する統計',
   'z値+1.4の人の偏差値（50＋10×z値で計算）はいくつ？',
   NULL::text,
   '["64", "60", "14", "78"]',
   0,
   '[0]',
   'single',
   '{"asked": "z値から偏差値を求める。偏差値＝50＋10×z値という決まった変換式を使う。", "point": "偏差値＝50＋10×z値。z値が0なら偏差値50、z値が+1なら偏差値60になるものさし。", "kid": "z値は「平均0・幅1」というものさしなので馴染みが薄い。これを「平均50・幅10」という、模試などでよく見る見慣れた数字に引き伸ばしたものが偏差値。", "eg": "z値は摂氏でいう「0度からの差」のような目盛り。偏差値はそれを「よく見る100点満点に近い数字」に変換したもの。変換のルールは常に同じ、50を足して10倍する。", "terms": [["偏差値", "50＋10×z値で計算する、平均50・標準偏差10のものさしに直した値"]], "think": "z値+1.4は「平均より標準偏差1.4個ぶん高い」という意味。これに10を掛けると「+14」という見慣れた幅の数字になり、さらに50を足すことで「平均が50」というよく見る基準に揃う。50を足すのを忘れると、z値を10倍しただけの中途半端な数のまま止まってしまう。", "calc": "z値       +1.4\n10倍      10 × 1.4 = 14\n偏差値    50 + 14 = 64", "vs": "偏差値64はもとの点数64点とたまたま同じ数字になっているが、これは今回の平均と標準偏差の組み合わせで偶然一致しただけで、いつも一致するわけではない。", "why_asked": "偏差値の式を丸暗記するのではなく、z値を「見慣れた幅に引き伸ばしただけ」と理解しているかを確かめる問い。50を足し忘れる・10倍を忘れるミスは実際によくある。", "usecase": "模試の成績表、入試の合格可能性判定など、異なるテスト間で成績の位置を比べるときに広く使われる。", "opt": ["正解。50+10×1.4=64。", "10×1.4を足すのを忘れて、50のまま答えてしまった場合の値。", "50を足すのを忘れて、10×1.4の14だけを答えてしまった場合の値。", "10倍のところを20倍と勘違いして50+28を計算した場合の値。"], "viz": "<svg viewBox=\"0 0 340 134\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n    <text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">z値を「平均50・標準偏差10」に引き伸ばす</text>\n    <line x1=\"30\" y1=\"42\" x2=\"310\" y2=\"42\" stroke=\"#2a2f3f\"/>\n    <text x=\"170\" y=\"35\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">z = 0</text>\n    <circle cx=\"240\" cy=\"42\" r=\"4.5\" fill=\"#3b82f6\"/>\n    <text x=\"240\" y=\"35\" fill=\"#3b82f6\" font-size=\"9\" text-anchor=\"middle\">z = +1.4</text>\n    <text x=\"170\" y=\"72\" fill=\"#60a5fa\" font-size=\"10\" text-anchor=\"middle\">↓ ×10して+50 ↓</text>\n    <line x1=\"30\" y1=\"102\" x2=\"310\" y2=\"102\" stroke=\"#2a2f3f\"/>\n    <text x=\"170\" y=\"95\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">偏差値50</text>\n    <circle cx=\"240\" cy=\"102\" r=\"4.5\" fill=\"#60a5fa\"/>\n    <text x=\"240\" y=\"120\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">偏差値 = ?</text>\n    </svg>"}'),  ('stats10-q09', '手で計算する統計',
   'サイコロを1回振るとき、出る目の平均的な大きさ（期待値）はいくつ？',
   NULL::text,
   '["3.5", "4.0", "21", "6"]',
   0,
   '[0]',
   'single',
   '{"asked": "サイコロの出る目の期待値を手で求める。", "point": "期待値＝すべての目を足して、目の数（6）で割った値。", "kid": "「サイコロを何度も振ったら、出た目の平均はだいたいどれくらいに落ち着くか」を計算で先に求めた値。", "eg": "1,2,3,4,5,6という6人分の点数があるとして、q01でやったのと同じように全部足して6人で割るだけ。テストの平均点の計算と、やっていることは同じ。", "terms": [["期待値", "起こりうる結果を全部足して、その数で割った平均的な値"]], "think": "サイコロは1〜6の目が同じ確率で出る。だから「平均するとどの値に落ち着くか」は、q01の平均点と同じやり方、全部足して個数で割る、で求められる。1〜6の合計21を6で割ると3.5になり、実際にサイコロにない目が答えになるのが期待値の面白いところ。", "calc": "目        1  2  3  4  5  6\n合計      1+2+3+4+5+6 = 21\n期待値    21 ÷ 6 = 3.5", "vs": "期待値3.5は実際にサイコロには出ない値。「一番出やすい目（最頻値）」や「よく出る目」ではなく、あくまで平均としての値であることに注意。", "why_asked": "ここまでの平均の計算（q01〜q08）が、テストの点数だけでなく「確率で決まる結果」にもそのまま使えることを確認する場面転換の問い。", "usecase": "ゲームの得点期待値、保険や賭け事の損得計算、機械学習の損失関数の設計など、「平均的にどうなるか」を先に見積もりたい場面で使う。", "opt": ["正解。1+2+3+4+5+6=21を6で割ると3.5。", "3.5を四捨五入して整数にしてしまった場合の値。", "6で割るのを忘れて、合計21のまま答えてしまった場合の値。", "一番大きい目をそのまま期待値だと勘違いした場合の値。"], "viz": "<svg viewBox=\"0 0 340 128\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n    <text x=\"170\" y=\"18\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">サイコロの目、ぜんぶ足して6で割ると？</text>\n    <rect x=\"26\" y=\"40\" width=\"28\" height=\"28\" rx=\"4\" fill=\"none\" stroke=\"#8892a4\"/><text x=\"40\" y=\"59\" fill=\"#e8eaf0\" font-size=\"12\" text-anchor=\"middle\">1</text><rect x=\"71\" y=\"40\" width=\"28\" height=\"28\" rx=\"4\" fill=\"none\" stroke=\"#8892a4\"/><text x=\"85\" y=\"59\" fill=\"#e8eaf0\" font-size=\"12\" text-anchor=\"middle\">2</text><rect x=\"116\" y=\"40\" width=\"28\" height=\"28\" rx=\"4\" fill=\"none\" stroke=\"#8892a4\"/><text x=\"130\" y=\"59\" fill=\"#e8eaf0\" font-size=\"12\" text-anchor=\"middle\">3</text><rect x=\"161\" y=\"40\" width=\"28\" height=\"28\" rx=\"4\" fill=\"none\" stroke=\"#8892a4\"/><text x=\"175\" y=\"59\" fill=\"#e8eaf0\" font-size=\"12\" text-anchor=\"middle\">4</text><rect x=\"206\" y=\"40\" width=\"28\" height=\"28\" rx=\"4\" fill=\"none\" stroke=\"#8892a4\"/><text x=\"220\" y=\"59\" fill=\"#e8eaf0\" font-size=\"12\" text-anchor=\"middle\">5</text><rect x=\"251\" y=\"40\" width=\"28\" height=\"28\" rx=\"4\" fill=\"none\" stroke=\"#8892a4\"/><text x=\"265\" y=\"59\" fill=\"#e8eaf0\" font-size=\"12\" text-anchor=\"middle\">6</text>\n    <line x1=\"30\" y1=\"90\" x2=\"310\" y2=\"90\" stroke=\"#2a2f3f\"/>\n    <line x1=\"153\" y1=\"84\" x2=\"153\" y2=\"96\" stroke=\"#c9a04a\" stroke-width=\"1.3\"/>\n    <text x=\"153\" y=\"112\" fill=\"#c9a04a\" font-size=\"10\" text-anchor=\"middle\">ここが期待値？</text>\n    </svg>"}'),  ('stats10-q10', '手で計算する統計',
   '10人に病気の検査をした結果、本当に病気で陽性と出た人(TP)が3人、本当に病気なのに陰性と出た人(FN)が1人、本当は健康なのに陽性と出た人(FP)が2人、本当に健康で陰性と出た人(TN)が4人だった。この検査の正解率は？',
   NULL::text,
   '["70%", "50%", "40%", "30%"]',
   0,
   '[0]',
   'single',
   '{"asked": "検査結果の4つの数（TP・FN・FP・TN）から正解率を手で求める。", "point": "正解率＝（当たった人数）÷（全員の人数）。当たったのはTP(陽性を陽性と当てた)とTN(陰性を陰性と当てた)。", "kid": "10人のうち、検査が「本当のこと」を言い当てられた人が何%いたかを表す数。", "eg": "10問のテストで、○をつけるべき問題に○、×をつけるべき問題に×と正しく答えられた数が「正解」。病気を病気と当てる(TP)、健康を健康と当てる(TN)がこの「正解」にあたる。", "terms": [["TP（真陽性）", "本当に陽性で、検査でも陽性と出た人数"], ["TN（真陰性）", "本当に陰性で、検査でも陰性と出た人数"], ["正解率", "全員のうち、検査が正しく判定できた人数の割合"]], "think": "10人のうち、当たったのはTP(病気を病気と当てた3人)とTN(健康を健康と当てた4人)の合計7人。外れたのはFN(1人)とFP(2人)の合計3人。当たった7人を全員10人で割ると70%になる。", "calc": "当たり     TP+TN = 3+4 = 7人\n全員       10人\n正解率     7 ÷ 10 = 0.70 = 70%", "vs": "「陽性と判定された人の割合」(TP+FP=5人、50%)や「本当に病気の人の割合」(TP+FN=4人、40%)と混同しやすいが、正解率は「当たったかどうか」だけを見る数値で、これらとは別の計算。", "why_asked": "正解率だけでは検査の良し悪しを判断できない場合がある（例えば病気の人が少ないと、全員「陰性」と答えるだけで正解率は高くなってしまう）ことを理解する土台になる問い。", "usecase": "病気の検査、迷惑メール判定、機械学習モデルの性能評価など、「当たり外れ」で結果を判定するあらゆる場面で使う指標。", "opt": ["正解。TP+TN=7人を10人で割ると70%。", "陽性と判定された人数(TP+FP=5人)を10人で割ってしまった場合の値。", "本当に病気だった人数(TP+FN=4人)を10人で割ってしまった場合の値。", "外れた人数(FN+FP=3人)を10人で割ってしまった場合の値。"], "viz": "<svg viewBox=\"0 0 340 134\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n    <text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">10人を検査した結果（混同行列）</text>\n    <rect x=\"100\" y=\"30\" width=\"80\" height=\"40\" fill=\"#6ab08d\" opacity=\"0.35\" stroke=\"#2a2f3f\"/>\n    <rect x=\"180\" y=\"30\" width=\"80\" height=\"40\" fill=\"#c47070\" opacity=\"0.35\" stroke=\"#2a2f3f\"/>\n    <rect x=\"100\" y=\"70\" width=\"80\" height=\"40\" fill=\"#c47070\" opacity=\"0.35\" stroke=\"#2a2f3f\"/>\n    <rect x=\"180\" y=\"70\" width=\"80\" height=\"40\" fill=\"#6ab08d\" opacity=\"0.35\" stroke=\"#2a2f3f\"/>\n    <text x=\"140\" y=\"54\" fill=\"#e8eaf0\" font-size=\"12\" text-anchor=\"middle\">TP=3</text>\n    <text x=\"220\" y=\"54\" fill=\"#e8eaf0\" font-size=\"12\" text-anchor=\"middle\">FN=1</text>\n    <text x=\"140\" y=\"94\" fill=\"#e8eaf0\" font-size=\"12\" text-anchor=\"middle\">FP=2</text>\n    <text x=\"220\" y=\"94\" fill=\"#e8eaf0\" font-size=\"12\" text-anchor=\"middle\">TN=4</text>\n    <text x=\"140\" y=\"26\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">陽性と判定</text>\n    <text x=\"220\" y=\"26\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">陰性と判定</text>\n    <text x=\"170\" y=\"122\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">緑(TP+TN)が「当たり」。10人中何%？</text>\n    </svg>"}'),  ('stats10-q11', '手で計算する統計',
   '同じ検査結果（TP=3, FN=1, FP=2, TN=4）で、「本当に病気だった4人」のうち、検査で正しく陽性と当てられた人の割合（再現率）は？',
   NULL::text,
   '["75%", "60%", "70%", "25%"]',
   0,
   '[0]',
   'single',
   '{"asked": "「本当に陽性だった人」の中で、検査が拾えた割合（再現率）を求める。", "point": "再現率＝TP÷（TP＋FN）。「本当に陽性の人」を分母にして、そのうち何人を陽性と当てられたかを見る。", "kid": "病気の人だけを集めてきて、そのうち検査が「病気です」と正しく見つけられた人の割合。", "eg": "空港の手荷物検査で、本当に危険物を持っていた人を何人見逃さずに見つけられたか、という割合。見逃し(FN)が多いと再現率は下がる。", "terms": [["再現率（さいげんりつ）", "本当に陽性の人のうち、検査で正しく陽性と当てられた人の割合。TP÷(TP+FN)"], ["適合率（てきごうりつ）", "検査が陽性と判定した人のうち、本当に陽性だった人の割合。TP÷(TP+FP)"]], "think": "「本当に病気だった人」はTP(3人)とFN(1人)を合わせた4人。このうち検査が正しく陽性と見つけられたのはTPの3人だけ。3を4で割ると75%になる。", "calc": "本当に陽性  TP+FN = 3+1 = 4人\n正しく検出  TP = 3人\n再現率      3 ÷ 4 = 0.75 = 75%", "vs": "適合率(TP÷(TP+FP)=3÷5=60%)は「陽性と判定した人」を分母にする、まったく別の割合。再現率は分母が「本当に陽性の人」である点が違う。", "why_asked": "正解率だけでは分からない「見逃しの少なさ」を測る指標。病気の検査のように見逃しが重大な場面では、正解率よりこちらを重視することがある。", "usecase": "病気の見逃しを避けたい検査、不良品の検出、詐欺の検知など「見逃したら困る」場面で重視される指標。", "opt": ["正解。TP÷(TP+FN)=3÷4=75%。", "適合率(TP÷(TP+FP)=3÷5=60%)と取り違えた場合の値。", "正解率(70%)と取り違えた場合の値。", "100%から75%を引いた「見逃した割合」を答えてしまった場合の値。"], "viz": "<svg viewBox=\"0 0 340 134\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n    <text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">「本当に陽性」の4人のうち何人を当てた？</text>\n    <rect x=\"100\" y=\"30\" width=\"80\" height=\"40\" fill=\"#6ab08d\" opacity=\"0.5\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/>\n    <rect x=\"180\" y=\"30\" width=\"80\" height=\"40\" fill=\"#c47070\" opacity=\"0.5\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/>\n    <rect x=\"100\" y=\"70\" width=\"80\" height=\"40\" fill=\"#c47070\" opacity=\"0.2\" stroke=\"#2a2f3f\"/>\n    <rect x=\"180\" y=\"70\" width=\"80\" height=\"40\" fill=\"#6ab08d\" opacity=\"0.2\" stroke=\"#2a2f3f\"/>\n    <text x=\"140\" y=\"54\" fill=\"#e8eaf0\" font-size=\"12\" text-anchor=\"middle\">TP=3</text>\n    <text x=\"220\" y=\"54\" fill=\"#e8eaf0\" font-size=\"12\" text-anchor=\"middle\">FN=1</text>\n    <text x=\"140\" y=\"94\" fill=\"#8892a4\" font-size=\"11\" text-anchor=\"middle\">FP=2</text>\n    <text x=\"220\" y=\"94\" fill=\"#8892a4\" font-size=\"11\" text-anchor=\"middle\">TN=4</text>\n    <text x=\"80\" y=\"50\" fill=\"#60a5fa\" font-size=\"9\" text-anchor=\"end\">本当に</text>\n    <text x=\"80\" y=\"62\" fill=\"#60a5fa\" font-size=\"9\" text-anchor=\"end\">陽性</text>\n    <text x=\"80\" y=\"90\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"end\">本当に</text>\n    <text x=\"80\" y=\"102\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"end\">陰性</text>\n    <text x=\"170\" y=\"122\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">枠で囲った2マス(TP+FN=4人)のうちTPは何%？</text>\n    </svg>"}'),  ('stats10-q12', '手で計算する統計',
   '適合率60%・再現率75%を1つの数にまとめる調和平均（F値）は、2×0.6×0.75÷(0.6+0.75)で計算する。答えを小数第2位までにするといくつ？',
   NULL::text,
   '["0.67", "0.68", "0.45", "1.35"]',
   0,
   '[0]',
   'single',
   '{"asked": "適合率と再現率を1つの数にまとめる調和平均（F値）を手で計算する。", "point": "F値は普通の平均（足して2で割る）ではなく、2×A×B÷(A＋B)で計算する「調和平均」を使う。", "kid": "適合率と再現率、2つの成績を「どちらも大事にしたバランスの取れた1つの点数」にまとめたもの。", "eg": "テストの点数の平均は普通「足して2で割る」だが、調和平均は違う計算方法。片方の点数が極端に低いと、もう片方が高くても全体の点数が大きく引っぱられて下がる、いわば「一番弱いところに厳しい」平均。", "terms": [["F値（F1スコア）", "適合率と再現率の調和平均。2×適合率×再現率÷(適合率+再現率)で計算する"], ["調和平均", "普通の平均とは別の計算方法で、小さい方の値に強く引っぱられる平均"]], "think": "適合率0.6と再現率0.75を普通に平均すると(0.6+0.75)÷2=0.675だが、F値はこの計算をしない。2×0.6×0.75÷(0.6+0.75)という調和平均の式を使うことで、片方だけが高くてもう片方が低いケースの点数を厳しめに評価する。実際に計算すると0.9÷1.35=0.666…となり、0.67になる。", "calc": "分子     2 × 0.6 × 0.75 = 0.9\n分母     0.6 + 0.75 = 1.35\nF値      0.9 ÷ 1.35 = 0.666… ≒ 0.67", "vs": "普通の平均(0.6+0.75)÷2=0.675と、F値0.67は近い値だが同じではない。適合率と再現率の差がもっと大きい場合は、この2つの差はさらに開く。", "why_asked": "適合率だけ、再現率だけを見ていると「片方だけ極端に高くもう片方が低い」モデルを見逃してしまう。F値はその歪みを1つの数で表すために使われる。", "usecase": "スパムメール判定、病気の検査、検索エンジンの精度評価など、適合率と再現率をトレードオフしながら1つの指標で性能を比べたいときに使う。", "opt": ["正解。0.9÷1.35=0.666…を小数第2位までにすると0.67。", "分子の0.9を計算する際の掛け算をわずかに間違えた場合に起こり得る値。", "分子の2×0.6×0.75だけを計算し、分母で割るのを忘れてしまった場合の値。", "分母の0.6+0.75=1.35をそのまま答えてしまった場合の値。"], "viz": "<svg viewBox=\"0 0 340 128\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n    <text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">適合率60%と再現率75%を1つにまとめる</text>\n    <line x1=\"30\" y1=\"45\" x2=\"310\" y2=\"45\" stroke=\"#2a2f3f\"/>\n    <circle cx=\"90\" cy=\"45\" r=\"4.5\" fill=\"#3b82f6\"/>\n    <text x=\"90\" y=\"38\" fill=\"#3b82f6\" font-size=\"9\" text-anchor=\"middle\">適合率60</text>\n    <circle cx=\"250\" cy=\"45\" r=\"4.5\" fill=\"#60a5fa\"/>\n    <text x=\"250\" y=\"38\" fill=\"#60a5fa\" font-size=\"9\" text-anchor=\"middle\">再現率75</text>\n    <text x=\"170\" y=\"68\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">ふつうの平均(足して2で割る)なら67.5</text>\n    <text x=\"170\" y=\"90\" fill=\"#c9a04a\" font-size=\"10\" text-anchor=\"middle\">F値は「小さい方に引っぱられる」特別な平均</text>\n    <text x=\"170\" y=\"112\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">2×0.6×0.75÷(0.6+0.75) = ?</text>\n    </svg>"}')
) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'stats-basics'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
